package org.autojs.autojs.core.ui.inflater

import android.content.Context
import com.google.gson.JsonObject
import com.google.gson.JsonParser
import java.util.concurrent.ConcurrentHashMap

/**
 * The Android XML attribute metadata of the dynamic layout inflater (host roadmap
 * `docs/dev/android-xml-attributes-roadmap.md` A1), generated by `.python/generate_android_attrs.py` from the Android
 * SDK (API 24 - 37, public attributes only) and the AndroidX / Material libraries the host ships, and read from the
 * asset [ASSET_PATH]. It answers which attributes a view class takes (its own and inherited styleables, the nearest
 * class first) and which its layout params take as a child of a given parent class, with formats, enum / flag values
 * and the API level an `android:` attribute appeared at (0 for library attributes). The inflater's fallback (A2 / A3)
 * converts values and picks setters with it; it does not decide whether a handler exists.
 *
 * zh-CN: 动态布局器的 Android XML 属性元数据 (宿主路线图 A1), 由生成器从 SDK (API 24 - 37, 仅公开属性) 与宿主自带的 AndroidX / Material
 * 库生成, 读自资产 [ASSET_PATH]. 回答某个 View 类 (含继承, 近者优先) 或某个父容器下的布局参数接受哪些属性, 及其格式, 枚举 / 标志取值与起始 API.
 */
class AndroidAttributeTable private constructor(root: JsonObject) {

    enum class Format(val key: String) {
        REFERENCE("reference"), COLOR("color"), DIMENSION("dimension"), FLOAT("float"), INTEGER("integer"),
        BOOLEAN("boolean"), STRING("string"), FRACTION("fraction"), ENUM("enum"), FLAG("flag");

        companion object {
            private val byKey = entries.associateBy { it.key }
            fun of(key: String): Format = byKey[key] ?: throw IllegalArgumentException("unknown attribute format $key")
        }
    }

    /** One attribute definition: [namespace] is `android` or `app`; [flags] values combine with `|`. */
    class Attr(
        val namespace: String,
        val name: String,
        val formats: Set<Format>,
        val enums: Map<String, Int>,
        val flags: Map<String, Int>,
    ) {
        val qualifiedName: String get() = "$namespace:$name"
    }

    /** An attribute as a member of [styleable] (`android:TextView`, `app:ConstraintLayout_Layout`), available since [sinceApi]. */
    class Member(val attr: Attr, val styleable: String, val sinceApi: Int)

    private val attrs: Map<String, Map<String, Attr>>
    private val styleables: Map<String, Map<String, Member>>
    private val classes: Map<String, List<String>>
    private val viewMembers = ConcurrentHashMap<Class<*>, Map<String, Member>>()
    private val layoutMembers = ConcurrentHashMap<Class<*>, Map<String, Member>>()

    init {
        require(root.get("schema")?.asInt == SCHEMA) { "unsupported android attribute table schema ${root.get("schema")}" }
        attrs = root.getAsJsonObject("attrs").entrySet().associate { (namespace, definitions) ->
            namespace to definitions.asJsonObject.entrySet().associate { (name, value) ->
                val definition = value.asJsonObject
                name to Attr(
                    namespace,
                    name,
                    definition.getAsJsonArray("f").map { Format.of(it.asString) }.toSet(),
                    definition.getAsJsonObject("e")?.entrySet()?.associate { it.key to it.value.asInt }.orEmpty(),
                    definition.getAsJsonObject("g")?.entrySet()?.associate { it.key to it.value.asInt }.orEmpty(),
                )
            }
        }
        styleables = root.getAsJsonObject("styleables").entrySet().associate { (key, members) ->
            val ownNamespace = key.substringBefore(':')
            key to members.asJsonObject.entrySet().mapNotNull { (name, since) ->
                val namespace = if (name.startsWith("android:")) "android" else ownNamespace
                val attr = attrs[namespace]?.get(name.removePrefix("android:")) ?: return@mapNotNull null
                attr.qualifiedName to Member(attr, key, since.asInt)
            }.toMap()
        }
        classes = root.getAsJsonObject("classes").entrySet().associate { (name, keys) -> name to keys.asJsonArray.map { it.asString } }
    }

    /** The definition of [namespace]:[name], or null when neither the SDK nor a bundled library defines it. */
    fun attr(namespace: String, name: String): Attr? = attrs[namespace]?.get(name)

    /** Every attribute [viewClass] takes by key `namespace:name`; a subclass's styleable wins over its superclass's. */
    fun membersOf(viewClass: Class<*>): Map<String, Member> = viewMembers.getOrPut(viewClass) { collect(viewClass, "") }

    /** Every attribute the layout params of a child of [parentClass] take, by key `namespace:name`. */
    fun layoutMembersOf(parentClass: Class<*>): Map<String, Member> = layoutMembers.getOrPut(parentClass) { collect(parentClass, LAYOUT_SUFFIX) }

    /**
     * The member [name] of [viewClass] in [namespace]; a null namespace (an unprefixed AutoJs6 attribute) or one the
     * class does not define the name in tries `android` first, then `app`, the way the inflater maps both prefixes
     * to the same handlers.
     */
    fun find(viewClass: Class<*>, namespace: String?, name: String): Member? = lookup(membersOf(viewClass), namespace, name)

    fun findLayout(parentClass: Class<*>, namespace: String?, name: String): Member? = lookup(layoutMembersOf(parentClass), namespace, name)

    private fun lookup(members: Map<String, Member>, namespace: String?, name: String): Member? {
        namespace?.let { members["$it:$name"]?.let { member -> return member } }
        return members["android:$name"] ?: members["app:$name"]
    }

    private fun collect(start: Class<*>, suffix: String): Map<String, Member> {
        val result = LinkedHashMap<String, Member>()
        var current: Class<*>? = start
        while (current != null && current != Any::class.java) {
            classes[current.name + suffix]?.forEach { key ->
                styleables[key]?.forEach { (name, member) -> result.putIfAbsent(name, member) }
            }
            current = current.superclass
        }
        return result
    }

    companion object {

        const val ASSET_PATH = "ui/android-attrs.json"
        const val SCHEMA = 1
        private const val LAYOUT_SUFFIX = "#layout"

        @Volatile
        private var instance: AndroidAttributeTable? = null

        /** The table of the app's assets, read once. */
        @JvmStatic
        fun get(context: Context): AndroidAttributeTable = instance ?: synchronized(this) {
            instance ?: context.applicationContext.assets.open(ASSET_PATH).use { parse(it.readBytes().toString(Charsets.UTF_8)) }.also { instance = it }
        }

        @JvmStatic
        fun parse(text: String): AndroidAttributeTable = AndroidAttributeTable(JsonParser.parseString(text).asJsonObject)
    }
}
